"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8714],{12719:e=>{e.exports=JSON.parse('{"functions":[{"name":"init","desc":"Bootstrap hook. Seeds `ClientState.coins` / `ClientState.xp` from the\\nprofile already in `ClientState.playerData`, then connects to\\n`playerData.Changed` to keep them in step.\\n\\nThe seed is safe because `Entry.client.luau` blocks on [DataController]\\nbefore bootstrapping controllers, so the profile is always present by the\\ntime this runs.","params":[],"returns":[],"function_type":"static","source":{"line":44,"path":"src/Client/Features/Core/Controllers/StatsController.luau"}}],"properties":[],"types":[],"name":"StatsController","desc":"Projects the two stats the HUD cares about out of the replicated profile\\nand into their own scalar states.\\n\\n[DataController] mirrors the whole profile into `ClientState.playerData`,\\nwhich is a coarse signal \u2014 it changes whenever *any* profile key changes.\\nComponents that only want the coin counter would re-render on every\\ninventory edit. So this controller keeps `ClientState.coins` and\\n`ClientState.xp` in step with `playerData.stats`, comparing before writing\\nso they only fire when the number actually moved.\\n\\n`RootOverlay` subscribes to `ClientState.coins.Changed` for the `Currency`\\ndisplay and its bounce animation.\\n\\nAdding another projected stat means adding a field to [ClientState] and\\nanother compare-and-set in the `Changed` handler here.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":24,"path":"src/Client/Features/Core/Controllers/StatsController.luau"}}')}}]);